def seed_road_types(apps, schema_editor):
    RoadType = apps.get_model('base', 'RoadType')
    History = apps.get_model('base', 'HistoricalRoadType')
    alias = schema_editor.connection.alias
    for name, description, priority in (
        ('Strada di 1° livello', 'Strada forestale camionabile', 10),
        ('Strada di 2° livello', 'Strada forestale adatta a macchine operatrici e automezzi 4x4', 20),
        ('Pista', 'Pista da esbosco per trattori e macchine forestali', 30),
        ('Sentiero', 'Percorso per pedoni o animali', 40),
    ):
        row = RoadType.objects.using(alias).create(
            name=name, description=description, sort_order=priority,
        )
        # Controllo uses this baseline to show the before value on the first edit.
        History.objects.using(alias).create(
            id=row.pk, name=name, description=description, sort_order=priority,
            active=row.active, version=row.version, created_at=row.created_at,
            modified_at=row.modified_at, history_date=row.created_at,
            history_type='+', history_change_reason='initial-audit-baseline',
        )


